from flask import Flask, Response

app = Flask(__name__)

HTML = r"""<!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#008080"><title>File Share 98 - PIN</title>
<style>
*{box-sizing:border-box}body{margin:0;padding:12px;background:#008080;font:14px Tahoma,Arial;color:#111;min-height:100vh}.window{max-width:760px;margin:18px auto;background:#c0c0c0;border:2px solid;border-color:#fff #404040 #404040 #fff;box-shadow:2px 2px #111}.title{margin:3px 3px 0;padding:8px;background:linear-gradient(90deg,#000080,#1084d0);color:white;font-weight:bold}.content{padding:14px}.panel{border:2px groove white;padding:12px;margin:0 0 12px}h2{font-size:15px;margin:0 0 10px}.muted{font-size:12px;color:#444;line-height:1.5}.btn{padding:10px 14px;min-height:42px;border:2px solid;border-color:white #404040 #404040 white;background:#c0c0c0;font:bold 14px Tahoma;cursor:pointer}.primary{background:#000080;color:white}.danger{background:#e4baba}.row{display:flex;gap:8px;flex-wrap:wrap}.row>*{flex:1}.pin{font:bold 34px "Courier New";letter-spacing:7px;text-align:center;background:#fff;border:2px inset #888;padding:12px;margin:12px 0}.field{width:100%;padding:12px;font:22px "Courier New";letter-spacing:5px;text-align:center;border:2px inset #888}.status{background:#eee;border:2px inset #888;padding:10px;min-height:42px;margin-top:10px;font-size:12px}.progress{height:20px;background:white;border:2px inset #888;margin:8px 0}.progress div{height:100%;width:0;background:#000080}.hidden{display:none!important}.file{display:block;margin:12px 0;max-width:100%}@media(max-width:520px){body{padding:4px}.window{margin:3px auto}.content{padding:9px}.panel{padding:9px}.pin{font-size:28px;letter-spacing:4px}}
</style></head><body><div class="window"><div class="title">🖥 FILE SHARE 98 — Trasferimento diretto</div><main class="content">
<section class="panel"><h2>🔒 Nessun archivio cloud</h2><p class="muted">Il PIN è temporaneo. I file vengono trasferiti direttamente tra i dispositivi, senza essere caricati sul sito. La stanza scade automaticamente dopo 10 minuti. Mantieni aperte entrambe le pagine durante il trasferimento.</p></section>
<section class="panel"><h2>📤 Invia da questo dispositivo</h2><button id="create" class="btn primary">Crea PIN temporaneo</button><div id="pinBox" class="hidden"><div class="pin" id="pin">--------</div><p class="muted">Inserisci questo PIN sul secondo dispositivo.</p><label class="btn file">Scegli file<input id="files" type="file" multiple hidden disabled></label></div></section>
<section class="panel"><h2>📥 Ricevi su questo dispositivo</h2><input id="joinPin" class="field" inputmode="numeric" maxlength="8" placeholder="PIN 8 CIFRE"><button id="join" class="btn primary" style="width:100%;margin-top:8px">Collega e ricevi</button><div id="received"></div></section>
<section class="panel"><h2>📊 Trasferimento</h2><div class="progress"><div id="bar"></div></div><div id="status" class="status" aria-live="polite">In attesa di connessione.</div><button id="close" class="btn danger" style="margin-top:8px" disabled>Chiudi sessione</button></section>
<p class="muted">File Share 98 · Android ⇄ iPhone · Fino a 3 GB per file (limite applicativo; la memoria del browser e la rete possono limitare i trasferimenti molto grandi).</p>
</main></div>
<script>
const SIGNAL_URL = "INSERISCI_URL_WORKER_CLOUDFLARE";
const MAX_FILE = 3000000000, CHUNK = 48 * 1024;
let pc=null, channel=null, roomPin=null, role=null, poller=null, receiveParts=[], receiveMeta=null, receivedBytes=0, busy=false;
const $=id=>document.getElementById(id);
function say(s){$('status').textContent=s}
function progress(p){$('bar').style.width=Math.max(0,Math.min(100,p))+'%'}
function api(path,method='GET',body){return fetch(SIGNAL_URL+path,{method,headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined}).then(async r=>{let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Errore di collegamento');return d})}
function waitIce(){return new Promise(resolve=>{if(pc.iceGatheringState==='complete')return resolve();const done=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',done);resolve()}};pc.addEventListener('icegatheringstatechange',done);setTimeout(resolve,12000)})}
function setupPeer(sender){pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});pc.onconnectionstatechange=()=>{say('Connessione: '+pc.connectionState);if(pc.connectionState==='failed')say('Connessione diretta non riuscita su questa rete. Riprova con entrambi i dispositivi sulla stessa Wi-Fi.')};if(sender){channel=pc.createDataChannel('files',{ordered:true});wireChannel()}else pc.ondatachannel=e=>{channel=e.channel;wireChannel()}}
function wireChannel(){channel.binaryType='arraybuffer';channel.onopen=()=>{say('Dispositivi collegati. Pronto al trasferimento.');$('close').disabled=false;if(role==='receiver')say('Collegato! Attendo i file…')};channel.onmessage=onData;channel.onerror=()=>say('Errore nel canale di trasferimento.')}
async function createRoom(){if(!SIGNAL_URL.startsWith('https://'))throw Error('Configura prima SIGNAL_URL con l’indirizzo del Worker.');const d=await api('/rooms','POST',{});roomPin=d.pin;role='sender';$('pin').textContent=roomPin;$('pinBox').classList.remove('hidden');setupPeer(true);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await waitIce();await api('/rooms/'+roomPin+'/offer','PUT',{sdp:pc.localDescription.sdp});say('PIN creato. In attesa che l’altro dispositivo si colleghi…');$('files').disabled=false;poller=setInterval(async()=>{try{const room=await api('/rooms/'+roomPin);if(room.answer&&pc.signalingState==='have-local-offer'){clearInterval(poller);await pc.setRemoteDescription({type:'answer',sdp:room.answer.sdp});say('Risposta ricevuta. Connessione in corso…')}}catch(e){clearInterval(poller);say(e.message)}},1200);$('close').disabled=false}
async function joinRoom(){const pin=$('joinPin').value.replace(/\D/g,'');if(!/^\d{8}$/.test(pin))throw Error('Inserisci un PIN di 8 cifre.');roomPin=pin;role='receiver';setupPeer(false);say('Ricerca del PIN…');let room=null;for(let i=0;i<30;i++){room=await api('/rooms/'+pin);if(room.offer)break;await new Promise(r=>setTimeout(r,1000))}if(!room||!room.offer)throw Error('PIN scaduto o non ancora disponibile.');await pc.setRemoteDescription({type:'offer',sdp:room.offer.sdp});const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await waitIce();await api('/rooms/'+pin+'/answer','PUT',{sdp:pc.localDescription.sdp});$('close').disabled=false;say('PIN riconosciuto. Collegamento in corso…')}
function waitDrain(){if(channel.bufferedAmount<1024*1024)return Promise.resolve();return new Promise(resolve=>{channel.bufferedAmountLowThreshold=256*1024;channel.onbufferedamountlow=()=>{channel.onbufferedamountlow=null;resolve()}})}
async function sendFiles(list){if(!channel||channel.readyState!=='open')throw Error('Prima collega il secondo dispositivo.');if(busy)return;busy=true;$('files').disabled=true;try{for(const file of list){if(file.size>MAX_FILE)throw Error(file.name+' supera 3 GB.');if(file.size===0)throw Error('File vuoto: '+file.name);channel.send(JSON.stringify({kind:'meta',name:file.name,size:file.size,type:file.type||'application/octet-stream'}));let sent=0;while(sent<file.size){await waitDrain();const part=file.slice(sent,Math.min(sent+CHUNK,file.size));channel.send(await part.arrayBuffer());sent+=part.size;progress(sent/file.size*100);say('Invio '+file.name+' — '+Math.round(sent/file.size*100)+'%')}channel.send(JSON.stringify({kind:'end'}));say('Inviato: '+file.name)}say('Trasferimento completato.')}finally{busy=false;$('files').disabled=false}}
function onData(e){if(typeof e.data==='string'){let m;try{m=JSON.parse(e.data)}catch{return}if(m.kind==='meta'){receiveMeta=m;receiveParts=[];receivedBytes=0;progress(0);say('Ricezione '+m.name+' ('+(m.size/1073741824).toFixed(2)+' GB)')}else if(m.kind==='end'&&receiveMeta){const blob=new Blob(receiveParts,{type:receiveMeta.type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=receiveMeta.name;a.textContent='Scarica '+receiveMeta.name+' ('+(blob.size/1048576).toFixed(1)+' MB)';a.className='btn primary file';$('received').append(a);say('Ricevuto '+receiveMeta.name+'. Tocca Scarica per salvarlo.');receiveParts=[];receiveMeta=null;progress(100)}return}if(receiveMeta){receiveParts.push(e.data);receivedBytes+=e.data.byteLength;progress(receivedBytes/receiveMeta.size*100);say('Ricezione in corso: '+Math.round(receivedBytes/receiveMeta.size*100)+'%')}}
function closeSession(){if(poller)clearInterval(poller);if(channel)channel.close();if(pc)pc.close();if(roomPin)api('/rooms/'+roomPin,'DELETE').catch(()=>{});pc=null;channel=null;roomPin=null;role=null;$('close').disabled=true;$('files').disabled=true;say('Sessione chiusa. Il PIN non è più disponibile.');progress(0)}
$('create').onclick=()=>createRoom().catch(e=>say(e.message));
$('join').onclick=()=>joinRoom().catch(e=>{say(e.message);if(pc)pc.close()});
$('files').onchange=e=>{const files=Array.from(e.target.files||[]);e.target.value='';sendFiles(files).catch(e=>say(e.message))};
$('close').onclick=closeSession;
window.addEventListener('pagehide',()=>{if(roomPin&&navigator.sendBeacon)navigator.sendBeacon(SIGNAL_URL+'/rooms/'+roomPin,'')});
</script></body></html>"""

@app.get("/")
def home():
    return Response(HTML, mimetype="text/html")
